import csv

def load(fn):
    with open(fn) as f:
        return list(csv.reader(f))

for fn in ["ae_ip_age_gender.csv","ae_ip_termination_by_month.csv","ae_ip_termination.csv"]:
    try:
        print("===== "+fn+" =====")
        rows = load(fn)
        for r in rows[:25]:
            print(r)
        print("total data rows:", len(rows)-1)
        print()
    except Exception as e:
        print(fn, "ERR", e)
        print()
